unit_test:
CLASS ltcl_test DEFINITION FOR TESTING RISK LEVEL HARMLESS DURATION SHORT.
  PRIVATE SECTION:
    METHODS test_parse_nested FOR TESTING RAISING cx_clb_parse_json_error.
ENDCLASS.

CLASS ltcl_test IMPLEMENTATION.
  METHOD test_parse_nested.
    DATA(lo_cut) = NEW zcl_json_nested_parser( ).
    DATA(lv_json) = |
      {{
        "order": {{
          "id": "ORD123",
          "customer": {{
            "name": "Max Mustermann",
            "email": "max@example.com"
          }},
          "totalAmount": 150.75,
          "items": [
            {{"item_name": "Book", "quantity": 1}},
            {{"item_name": "Pen", "quantity": 5}}
          ]
        }}
      }}
    |.

    DATA(ls_result) = lo_cut->parse_nested_json( lv_json ).

    cl_abap_unit_assert=>assert_equals( act = ls_result-order_id exp = 'ORD123' ).
    cl_abap_unit_assert=>assert_equals( act = ls_result-customer_name exp = 'Max Mustermann' ).
    cl_abap_unit_assert=>assert_equals( act = ls_result-total_amount exp = '150.75' ).
    cl_abap_unit_assert=>assert_equals( act = lines( ls_result-details ) exp = 2 ).

    READ TABLE ls_result-details INDEX 1 INTO DATA(ls_detail).
    cl_abap_unit_assert=>assert_equals( act = ls_detail-item_name exp = 'Book' ).
    cl_abap_unit_assert=>assert_equals( act = ls_detail-quantity exp = 1 ).
  ENDMETHOD.
ENDCLASS.
